// Format retrieved chunks into augmented prompt with patient context
const chunks = $input.all();
const user_input = $('Set Text Input').first().json.user_input;
const patient_context = $('Format Patient Context (Text)').first().json.context;

let referenceText = "";

if (chunks && chunks.length > 0) {
  const firstChunk = chunks[0].json;

  if (firstChunk.documents && firstChunk.documents[0]) {
    const documents = firstChunk.documents[0];
    const metadatas = firstChunk.metadatas ? firstChunk.metadatas[0] : [];

    for (let i = 0; i < documents.length; i++) {
      const doc = documents[i];
      const meta = metadatas[i] || {};
      const bookName = meta.book_name || 'Unknown Book';
      const pageNum = meta.estimated_page || 'Unknown Page';

      referenceText += `[${bookName} - Page ${pageNum}]:\n${doc}\n\n`;
    }
  }
}

if (!referenceText) {
  referenceText = "কোনো প্রাসঙ্গিক তথ্য পাওয়া যায়নি।";
}

const augmentedPrompt = `[PATIENT CONTEXT]: ${patient_context}\n\nনিচের রেফারেন্স অংশগুলো ব্যবহার করে প্রশ্নের উত্তর দাও। রেফারেন্সে না থাকলে অনুমান করে বানিয়ে বোলো না, বরং জানাও যে এই বিষয়ে নির্দিষ্ট তথ্য নেই:\n\n${referenceText}\n\nপ্রশ্ন: ${user_input}`;

return {
  json: {
    augmented_prompt: augmentedPrompt,
    user_input: user_input,
    patient_context: patient_context,
    reference_count: referenceText ? (chunks[0].json.documents[0]?.length || 0) : 0
  }
};

